// Base history: build mobile (bundel lokal) di-serve dari root '/', build web
// portal di-serve dari '/portal/'.
const router = createRouter({
	history: createWebHistory(import.meta.env.VITE_MOBILE ? '/' : '/portal/'),
	routes,
})

// Halaman yang boleh dibuka tanpa login.
const GUEST_ROUTES = ['Login', 'ForgotPassword']

// Route guard: paksa ke login kalau belum auth
router.beforeEach((to, from, next) => {
	const isLoggedIn = session.isLoggedIn
	const isGuestRoute = GUEST_ROUTES.includes(to.name)
	if (!isGuestRoute && !isLoggedIn) {
		next({ name: 'Login' })
	} else if (isGuestRoute && isLoggedIn) {
		next({ name: 'Home' })
	} else {
		next()
	}
})

// Muat semua chunk halaman satu per satu di latar setelah navigasi pertama
// selesai, supaya perpindahan menu tetap instan (terutama di APK). Berurutan,
// bukan sekaligus, agar tidak berebut jaringan/CPU dengan layar yang sedang
// dibuka. Gagal di satu halaman tidak menghentikan sisanya.
function prefetchPages() {
	const idle = window.requestIdleCallback || ((cb) => setTimeout(cb, 1500))
	idle(() => {
		lazyPages.reduce((p, load) => p.then(() => load().catch(() => {})), Promise.resolve())
	})
}
router.isReady().then(prefetchPages)

// Setelah deploy, chunk lama terhapus (nama file ber-hash). Tab yang masih
// memakai build lama akan gagal memuat chunk → muat ulang penuh ke tujuan agar
// mendapat build terbaru. Dijaga sekali per tujuan supaya tidak reload berulang.
router.onError((err, to) => {
	const msg = String((err && err.message) || '')
	if (!/dynamically imported module|Importing a module script failed|Failed to fetch/i.test(msg))
		return
	const href = router.resolve(to).href
	try {
		if (sessionStorage.getItem('chunk-reload') === href) return
		sessionStorage.setItem('chunk-reload', href)
	} catch (e) {
		/* abaikan */
	}
	window.location.assign(href)
})
router.afterEach(() => {
	try {
		sessionStorage.removeItem('chunk-reload')
	} catch (e) {
		/* abaikan */
	}
})

export default router
