import { computed } from 'vue'
import { currentUser } from '../data/user'
import { DEPARTMENTS, MENU_ITEMS } from '../config/apps'
import { NOTIFICATIONS } from '../config/notifications'

/**
 * Turunkan tampilan home (chip role, menu, notifikasi) dari role ASLI user.
 * Semua reactive — saat role selesai di-fetch, UI otomatis update.
 */
export function useRoleMenu() {
	const roles = computed(() => currentUser.roles || [])
	const ready = computed(() => currentUser.rolesLoaded)

	// Department = entry pertama yang salah satu role-nya dimiliki user.
	// null kalau tidak ada yang cocok (jangan asal fallback ke department lain).
	const department = computed(() => {
		for (const d of DEPARTMENTS) {
			if (d.roles.some((r) => roles.value.includes(r))) return d
		}
		return null
	})

	// Chip: role department yang cocok; kalau tidak ada, pakai role pertama.
	const roleLabel = computed(() => {
		if (department.value) {
			return department.value.roles.find((r) => roles.value.includes(r)) || roles.value[0]
		}
		return roles.value[0] || '—'
	})

	// Menu = daftar key department → definisi MENU_ITEMS (urut sesuai config).
	const menu = computed(() => {
		if (!department.value) return []
		return department.value.menu
			.map((key) => (MENU_ITEMS[key] ? { key, ...MENU_ITEMS[key] } : null))
			.filter(Boolean)
	})

	const notifications = computed(() =>
		department.value ? NOTIFICATIONS[department.value.key] || [] : []
	)

	return { roles, ready, department, roleLabel, menu, notifications }
}
