import { onBeforeUnmount, ref, watch } from 'vue'
import { currentUser } from '../data/user'

const PROFILE_PHOTO_ENDPOINT = '/api/method/juragan.api.portal.roles.get_my_profile_photo'

/**
 * Foto profil User yang aman untuk portal web dan aplikasi native.
 *
 * File lokal diambil sebagai blob melalui fetch agar shim native dapat
 * menyertakan token Authorization. URL eksternal (mis. Gravatar) dipakai
 * langsung karena tidak memiliki record File di server.
 */
export function useProfilePhoto() {
	const profilePhotoUrl = ref('')
	const photoFailed = ref(false)
	let loadSequence = 0

	function revokePhoto() {
		if (!profilePhotoUrl.value) return
		URL.revokeObjectURL(profilePhotoUrl.value)
		profilePhotoUrl.value = ''
	}

	async function reloadProfilePhoto(userImage = currentUser.userImage) {
		const sequence = ++loadSequence
		revokePhoto()
		photoFailed.value = false
		if (!userImage) return

		if (!userImage.startsWith('/')) {
			profilePhotoUrl.value = userImage
			return
		}

		try {
			const res = await fetch(PROFILE_PHOTO_ENDPOINT, {
				credentials: 'include',
				headers: { Accept: 'image/*' },
			})
			if (!res.ok) throw new Error(`HTTP ${res.status}`)
			const blob = await res.blob()
			if (!blob.type.startsWith('image/')) throw new Error('Respons bukan gambar')
			if (sequence !== loadSequence) return
			profilePhotoUrl.value = URL.createObjectURL(blob)
		} catch (e) {
			// Foto adalah pelengkap; pemanggil menampilkan avatar bawaan jika gagal.
			if (sequence === loadSequence) photoFailed.value = true
		}
	}

	watch(() => currentUser.userImage, reloadProfilePhoto, { immediate: true })
	onBeforeUnmount(() => {
		loadSequence++
		revokePhoto()
	})

	return { profilePhotoUrl, photoFailed, reloadProfilePhoto }
}
