/**
 * Format angka & warna untuk tampilan Realisasi Collection.
 *
 * Dipakai bersama oleh halaman penuh (pages/RealisasiCollection.vue) dan kartu
 * preview di Home (components/DashboardCarousel.vue) supaya keduanya tidak
 * pernah menampilkan angka atau warna yang berbeda untuk data yang sama.
 *
 * Ambang warna persentase mengikuti get_percentage_class pada desk page
 * realisasi_collection: di bawah 85 merah, 85 sampai 97 kuning, 97 ke atas hijau.
 */

export const PCT_DANGER = '#ef4444'
export const PCT_WARNING = '#f59e0b'
export const PCT_SUCCESS = '#22c55e'

export function fmtNum(value, digits = 0) {
	return new Intl.NumberFormat('id-ID', { maximumFractionDigits: digits }).format(
		Number(value) || 0
	)
}

/**
 * Angka dengan jumlah desimal TETAP — nol di belakang koma ikut ditulis.
 *
 * `fmtNum` hanya membatasi desimal maksimum, sehingga 69,9 tetap tampil "69,9"
 * meski diminta dua angka. Persentase memakai fungsi ini supaya seluruh angka
 * di portal berbaris rapi dengan dua desimal.
 */
export function fmtNumFixed(value, digits = 2) {
	return new Intl.NumberFormat('id-ID', {
		minimumFractionDigits: digits,
		maximumFractionDigits: digits,
	}).format(Number(value) || 0)
}

export function fmtPct(value) {
	if (value === null || value === undefined) return '-'
	return `${fmtNumFixed(value, 2)}%`
}

/**
 * Rupiah diringkas (rb / Jt / M / T) supaya angka besar tetap terbaca di layar
 * ponsel. Nilai penuhnya disediakan lewat fmtIdrFull di tempat yang muat.
 */
export function fmtIdrShort(value) {
	const n = Number(value) || 0
	const abs = Math.abs(n)
	const sign = n < 0 ? '-' : ''
	if (abs >= 1e12) return `${sign}Rp ${fmtNum(abs / 1e12, 2)} T`
	if (abs >= 1e9) return `${sign}Rp ${fmtNum(abs / 1e9, 2)} M`
	if (abs >= 1e6) return `${sign}Rp ${fmtNum(abs / 1e6, 1)} Jt`
	if (abs >= 1e3) return `${sign}Rp ${fmtNum(abs / 1e3, 0)} rb`
	return `${sign}Rp ${fmtNum(abs, 0)}`
}

export function fmtIdrFull(value) {
	return new Intl.NumberFormat('id-ID', {
		style: 'currency',
		currency: 'IDR',
		minimumFractionDigits: 0,
	}).format(Number(value) || 0)
}

/** Nilai metrik menurut mode: mode Amount memakai rupiah, selain itu unit. */
export function fmtMetric(value, isCurrency) {
	if (value === null || value === undefined) return '-'
	return isCurrency ? fmtIdrShort(value) : `${fmtNum(value, 0)} unit`
}

export function fmtMetricFull(value, isCurrency) {
	if (value === null || value === undefined) return '-'
	return isCurrency ? fmtIdrFull(value) : `${fmtNum(value, 0)} unit`
}

/** Persentase untuk lebar bar / panjang busur cincin, dipotong ke 0..100. */
export function clampPct(value) {
	return Math.min(100, Math.max(0, Number(value) || 0))
}

export function pctColor(value) {
	const p = Number(value) || 0
	if (p < 85) return PCT_DANGER
	if (p < 97) return PCT_WARNING
	return PCT_SUCCESS
}

export function pctBadgeClass(value) {
	const p = Number(value) || 0
	if (p < 85) return 'bg-ui-surface-red-50 text-ui-ink-red-600'
	if (p < 97) return 'bg-ui-surface-amber-50 text-ui-ink-amber-600'
	return 'bg-ui-surface-emerald-50 text-ui-ink-emerald-600'
}
