<template>
	<!-- Overlay gambar full-screen (in-app). Aktif saat imageState.open. -->
	<Teleport to="body">
		<div v-if="imageState.open" class="fixed inset-0 z-[60] flex flex-col bg-[#171717]">
			<!-- Header: back kiri · judul · zoom · download kanan -->
			<div
				class="flex items-center gap-2 border-b border-white/10 px-3 py-3"
				style="padding-top: calc(0.75rem + env(safe-area-inset-top))"
			>
				<button
					type="button"
					class="flex h-10 w-10 shrink-0 items-center justify-center rounded-lg text-white/90 hover:bg-white/10 active:bg-white/20"
					aria-label="Kembali"
					@click="closeImage"
				>
					<svg
						xmlns="http://www.w3.org/2000/svg"
						viewBox="0 0 24 24"
						class="h-6 w-6"
						fill="none"
						stroke="currentColor"
						stroke-width="2"
						stroke-linecap="round"
						stroke-linejoin="round"
					>
						<path d="m12 19-7-7 7-7" />
						<path d="M19 12H5" />
					</svg>
				</button>
				<span class="min-w-0 flex-1 truncate text-sm font-medium text-white">{{
					imageState.title
				}}</span>
				<button
					type="button"
					class="flex h-10 w-10 shrink-0 items-center justify-center rounded-lg text-white/90 hover:bg-white/10 active:bg-white/20 disabled:opacity-40"
					aria-label="Perkecil"
					:disabled="!objectUrl || scale <= MIN_SCALE"
					@click="zoomStep(1 / 1.5)"
				>
					<svg
						xmlns="http://www.w3.org/2000/svg"
						viewBox="0 0 24 24"
						class="h-5 w-5"
						fill="none"
						stroke="currentColor"
						stroke-width="2"
						stroke-linecap="round"
					>
						<path d="M5 12h14" />
					</svg>
				</button>
				<button
					type="button"
					class="flex h-10 w-10 shrink-0 items-center justify-center rounded-lg text-white/90 hover:bg-white/10 active:bg-white/20 disabled:opacity-40"
					aria-label="Perbesar"
					:disabled="!objectUrl || scale >= MAX_SCALE"
					@click="zoomStep(1.5)"
				>
					<svg
						xmlns="http://www.w3.org/2000/svg"
						viewBox="0 0 24 24"
						class="h-5 w-5"
						fill="none"
						stroke="currentColor"
						stroke-width="2"
						stroke-linecap="round"
					>
						<path d="M12 5v14M5 12h14" />
					</svg>
				</button>
				<button
					type="button"
					:disabled="downloading || !objectUrl"
					class="flex h-10 w-10 shrink-0 items-center justify-center rounded-lg text-white/90 hover:bg-white/10 active:bg-white/20 disabled:opacity-40"
					aria-label="Unduh"
					@click="download"
				>
					<svg
						xmlns="http://www.w3.org/2000/svg"
						viewBox="0 0 24 24"
						class="h-6 w-6"
						fill="none"
						stroke="currentColor"
						stroke-width="2"
						stroke-linecap="round"
						stroke-linejoin="round"
					>
						<path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4" />
						<polyline points="7 10 12 15 17 10" />
						<line x1="12" y1="15" x2="12" y2="3" />
					</svg>
				</button>
			</div>

			<!-- Isi. `touch-action: none` → semua sentuhan (cubit & geser) ditangani
			     handler di bawah, bukan oleh browser. Gambar digeser/diperbesar lewat
			     CSS transform, jadi tidak perlu scrollbar. -->
			<div
				ref="stage"
				class="flex flex-1 items-center justify-center overflow-hidden p-4"
				style="touch-action: none; overscroll-behavior: contain"
				@touchstart="onTouchStart"
				@touchmove="onTouchMove"
				@touchend="onTouchEnd"
				@touchcancel="onTouchEnd"
				@wheel="onWheel"
				@mousedown="onMouseDown"
				@dblclick="onDblClick"
			>
				<p v-if="loading" class="text-sm text-white/70">Memuat gambar…</p>
				<pre
					v-else-if="error"
					class="text-center text-sm whitespace-pre-wrap text-red-300"
					>{{ error }}</pre
				>
				<img
					v-else-if="objectUrl"
					ref="imgEl"
					:src="objectUrl"
					:alt="imageState.title"
					class="max-h-full max-w-full object-contain select-none"
					draggable="false"
					:style="imgStyle"
					@load="resetView"
				/>
			</div>
		</div>
	</Teleport>
</template>

<script setup>
import { computed, reactive, ref, watch, onBeforeUnmount } from 'vue'
import { imageState, closeImage } from '../composables/attachmentViewer'
import { isNativeApp } from '../data/mobile'
import { fetchBinaryNative } from '../data/nativeHttp'

const loading = ref(false)
const error = ref('')
const objectUrl = ref('')
const downloading = ref(false)

function revoke() {
	if (objectUrl.value) {
		try {
			URL.revokeObjectURL(objectUrl.value)
		} catch (e) {
			/* ignore */
		}
		objectUrl.value = ''
	}
}

async function load(url) {
	revoke()
	error.value = ''
	resetView()
	if (!url) return
	loading.value = true
	try {
		let blob
		if (isNativeApp()) {
			// Native: ambil via HTTP native (bypass CORS file statis nginx).
			const { bytes, contentType } = await fetchBinaryNative(url)
			blob = new Blob([bytes], { type: contentType })
		} else {
			// Web: fetch same-origin biasa.
			const res = await fetch(url)
			if (!res.ok) throw new Error(`HTTP ${res.status}`)
			blob = await res.blob()
		}
		objectUrl.value = URL.createObjectURL(blob)
	} catch (e) {
		error.value = 'Gagal memuat gambar.\n' + (e?.message || e)
	} finally {
		loading.value = false
	}
}

function download() {
	if (!objectUrl.value) return
	downloading.value = true
	try {
		const a = document.createElement('a')
		a.href = objectUrl.value
		a.download = (imageState.title || 'gambar').split(/[?#]/)[0]
		document.body.appendChild(a)
		a.click()
		a.remove()
	} finally {
		downloading.value = false
	}
}

// --- Zoom & geser -------------------------------------------------------------
//
// Model tampilannya sederhana: gambar tetap di-layout menempel layar
// (object-contain), lalu seluruh tampilan diatur satu transform
// `translate(tx,ty) scale(s)` dengan titik acuan tengah gambar. Karena titik
// acuannya tengah dan gambar memang di tengah stage, posisi layar sebuah titik
// gambar = pusat stage + titik×skala + geseran. Rumus itu yang dipakai untuk
// menahan titik cubitan tetap di bawah jari.
const MIN_SCALE = 1
const MAX_SCALE = 5

const stage = ref(null)
const imgEl = ref(null)
const scale = ref(1)
const offset = reactive({ x: 0, y: 0 })
// Animasi hanya untuk zoom lewat tombol / ketuk dua kali — saat jari masih
// menempel transform harus mengikuti seketika.
const animating = ref(false)

const imgStyle = computed(() => ({
	transform: `translate(${offset.x}px, ${offset.y}px) scale(${scale.value})`,
	transformOrigin: 'center',
	transition: animating.value ? 'transform 180ms ease-out' : 'none',
	cursor: scale.value > 1 ? 'grab' : 'auto',
	willChange: 'transform',
}))

function resetView() {
	scale.value = 1
	offset.x = 0
	offset.y = 0
	animating.value = false
}

function clampScale(v) {
	return Math.min(MAX_SCALE, Math.max(MIN_SCALE, v))
}

// Batasi geseran supaya gambar tidak bisa ditarik keluar layar: saat gambar
// (setelah diperbesar) lebih kecil dari stage, geseran dikunci 0 → tetap center.
function clampOffset() {
	const st = stage.value
	const im = imgEl.value
	if (!st || !im) return
	const maxX = Math.max(0, (im.offsetWidth * scale.value - st.clientWidth) / 2)
	const maxY = Math.max(0, (im.offsetHeight * scale.value - st.clientHeight) / 2)
	offset.x = Math.min(maxX, Math.max(-maxX, offset.x))
	offset.y = Math.min(maxY, Math.max(-maxY, offset.y))
}

// Pusat stage dalam koordinat layar = titik acuan transform gambar.
function stageCenter() {
	const st = stage.value
	if (!st) return null
	const r = st.getBoundingClientRect()
	return { x: r.left + r.width / 2, y: r.top + r.height / 2 }
}

// Ubah skala ke `next` sambil menahan titik gambar yang berada di (fx, fy)
// (koordinat layar) supaya tetap di situ.
function zoomTo(next, fx, fy, base) {
	const c = stageCenter()
	if (!c) return
	const from = base || { s: scale.value, x: offset.x, y: offset.y }
	const target = clampScale(next)
	const ratio = target / from.s
	scale.value = target
	offset.x = (fx - c.x) * (1 - ratio) + from.x * ratio
	offset.y = (fy - c.y) * (1 - ratio) + from.y * ratio
	clampOffset()
}

function zoomStep(factor) {
	const c = stageCenter()
	if (!c) return
	animating.value = true
	zoomTo(scale.value * factor, c.x, c.y)
	setTimeout(() => (animating.value = false), 200)
}

function toggleZoom(fx, fy) {
	animating.value = true
	zoomTo(scale.value > 1.05 ? 1 : 2.5, fx, fy)
	setTimeout(() => (animating.value = false), 200)
}

// --- Sentuh: cubit untuk zoom, satu jari untuk geser, ketuk 2× untuk toggle ----
let pinch = null
let drag = null
let lastTapAt = 0
let lastTapXY = null
let tapMoved = false
let lastTouchAt = 0

function two(e) {
	const [a, b] = e.touches
	return {
		dist: Math.hypot(b.clientX - a.clientX, b.clientY - a.clientY) || 1,
		mid: { x: (a.clientX + b.clientX) / 2, y: (a.clientY + b.clientY) / 2 },
	}
}

function onTouchStart(e) {
	if (!objectUrl.value) return
	animating.value = false
	lastTouchAt = Date.now()
	if (e.touches.length === 2) {
		const { dist, mid } = two(e)
		pinch = {
			dist,
			mid,
			base: { s: scale.value, x: offset.x, y: offset.y },
		}
		drag = null
		return
	}
	if (e.touches.length === 1) {
		const t = e.touches[0]
		tapMoved = false
		drag = { x: t.clientX, y: t.clientY }
	}
}

function onTouchMove(e) {
	if (!objectUrl.value) return
	if (pinch && e.touches.length === 2) {
		e.preventDefault()
		const { dist, mid } = two(e)
		// Zoom di titik cubitan awal, lalu geser mengikuti perpindahan titik tengah
		// dua jari (jadi bisa zoom sambil menggeser, seperti galeri foto).
		zoomTo(pinch.base.s * (dist / pinch.dist), pinch.mid.x, pinch.mid.y, pinch.base)
		offset.x += mid.x - pinch.mid.x
		offset.y += mid.y - pinch.mid.y
		clampOffset()
		return
	}
	if (drag && e.touches.length === 1) {
		const t = e.touches[0]
		const dx = t.clientX - drag.x
		const dy = t.clientY - drag.y
		if (Math.hypot(dx, dy) > 10) tapMoved = true
		if (scale.value > 1) {
			e.preventDefault()
			offset.x += dx
			offset.y += dy
			clampOffset()
		}
		drag = { x: t.clientX, y: t.clientY }
	}
}

function onTouchEnd(e) {
	lastTouchAt = Date.now()
	if (pinch) {
		if (e.touches.length === 0) pinch = null
		drag = null
		return
	}
	const t = e.changedTouches && e.changedTouches[0]
	drag = null
	if (!t || e.touches.length || tapMoved || !objectUrl.value) return
	const now = Date.now()
	const near = lastTapXY && Math.hypot(t.clientX - lastTapXY.x, t.clientY - lastTapXY.y) < 40
	if (now - lastTapAt < 300 && near) {
		lastTapAt = 0
		lastTapXY = null
		toggleZoom(t.clientX, t.clientY)
		return
	}
	lastTapAt = now
	lastTapXY = { x: t.clientX, y: t.clientY }
}

// --- Mouse / trackpad (web) ---------------------------------------------------
function onWheel(e) {
	if (!objectUrl.value) return
	// Di lightbox tidak ada yang perlu di-scroll → semua putaran roda jadi zoom.
	e.preventDefault()
	animating.value = false
	zoomTo(scale.value * Math.exp(-e.deltaY / 300), e.clientX, e.clientY)
}

function onMouseDown(e) {
	if (!objectUrl.value || scale.value <= 1 || e.button !== 0) return
	e.preventDefault()
	let last = { x: e.clientX, y: e.clientY }
	const move = (ev) => {
		offset.x += ev.clientX - last.x
		offset.y += ev.clientY - last.y
		last = { x: ev.clientX, y: ev.clientY }
		clampOffset()
	}
	const up = () => {
		window.removeEventListener('mousemove', move)
		window.removeEventListener('mouseup', up)
	}
	window.addEventListener('mousemove', move)
	window.addEventListener('mouseup', up)
}

function onDblClick(e) {
	// Ketukan layar sudah ditangani onTouchEnd; abaikan dblclick turunannya.
	if (!objectUrl.value || Date.now() - lastTouchAt < 700) return
	toggleZoom(e.clientX, e.clientY)
}

// Ukuran stage berubah (putar layar) → pastikan gambar tidak tertinggal di luar.
function onResize() {
	if (imageState.open) clampOffset()
}
window.addEventListener('resize', onResize)

watch(
	() => (imageState.open ? imageState.url : ''),
	(url) => {
		if (url) load(url)
		else revoke()
	},
)

onBeforeUnmount(() => {
	window.removeEventListener('resize', onResize)
	revoke()
})
</script>
