<template>
	<!--
		Pop-up wajib "Lengkapi Profil" untuk CMO yang belum pernah melengkapi profil.
		Cermin dialog desk (public/js/show_profile_dialog.js): field & endpoint
		simpannya sama, jadi profil yang dilengkapi di sini tidak ditanyakan lagi di
		desk, dan sebaliknya. Tidak ada tombol tutup dan klik di luar pop-up tidak
		menutupnya — satu-satunya jalan keluar adalah menyimpan profil.
	-->
	<div
		v-if="currentUser.profileRequired"
		class="fixed inset-0 z-[80] flex items-center justify-center bg-black/40 px-4"
		style="
			padding-top: calc(1rem + env(safe-area-inset-top));
			padding-bottom: calc(1rem + env(safe-area-inset-bottom));
		"
		role="dialog"
		aria-modal="true"
		aria-labelledby="profile-setup-title"
	>
		<div
			class="flex max-h-full w-full max-w-md flex-col overflow-hidden rounded-[1.75rem] bg-ui-surface shadow-xl"
		>
			<div class="border-b border-ui-line-gray-200 px-6 py-4">
				<h2 id="profile-setup-title" class="font-semibold text-ui-ink-gray-900">
					Lengkapi Profil
				</h2>
			</div>

			<div
				v-if="memuat"
				class="flex items-center justify-center gap-2 py-12 text-sm text-ui-ink-gray-600"
			>
				<Spinner />
				<span>Memuat...</span>
			</div>

			<div v-else-if="gagalMemuat" class="px-6 py-8 text-center">
				<p class="text-sm text-ui-ink-gray-700">{{ gagalMemuat }}</p>
				<button
					type="button"
					class="mt-4 rounded-[1.25rem] bg-primary px-6 py-3 text-sm font-semibold text-ui-onPrimary"
					@click="muat"
				>
					Coba Lagi
				</button>
			</div>

			<form v-else class="flex min-h-0 flex-col" @submit.prevent="simpan">
				<div class="min-h-0 flex-1 space-y-5 overflow-y-auto px-6 py-5">
					<!-- Informasi Akun (read-only) -->
					<div>
						<p
							class="mb-2 text-xs font-semibold uppercase tracking-wide text-ui-ink-gray-500"
						>
							Informasi Akun
						</p>
						<dl class="grid grid-cols-2 gap-x-4 gap-y-3 rounded-[1.25rem] bg-ui-surface-gray-50 px-4 py-3">
							<div
								v-for="item in infoAkun"
								:key="item.label"
								:class="{ 'col-span-2': item.lebar }"
							>
								<dt class="text-xs text-ui-ink-gray-500">{{ item.label }}</dt>
								<dd class="break-words text-sm font-medium text-ui-ink-gray-900">
									{{ item.value || '—' }}
								</dd>
							</div>
						</dl>
					</div>

					<div>
						<label
							for="profile-setup-wa"
							class="mb-1.5 block text-sm font-medium text-ui-ink-gray-900"
						>
							No WhatsApp <span class="text-ui-ink-red-600">*</span>
						</label>
						<input
							id="profile-setup-wa"
							v-model="noWhatsapp"
							type="tel"
							inputmode="tel"
							autocomplete="tel"
							placeholder="08xxxxxxxxxx"
							class="w-full rounded-[1.25rem] border border-ui-heading bg-transparent px-5 py-3 text-ui-ink placeholder-ui-ink-gray-600 focus:outline-none focus:ring-1 focus:ring-ui-heading"
						/>
					</div>

					<div>
						<div class="mb-1.5 flex items-center justify-between">
							<span class="text-sm font-medium text-ui-ink-gray-900">
								Tanda Tangan <span class="text-ui-ink-red-600">*</span>
							</span>
							<button
								type="button"
								class="text-sm font-medium text-ui-action disabled:opacity-40"
								:disabled="ttdKosong"
								@click="hapusTtd"
							>
								Hapus
							</button>
						</div>
						<!-- Latar putih permanen (juga di mode gelap): gambar TTD disimpan
						     sebagai PNG tinta hitam dan dipakai di print format. -->
						<canvas
							ref="canvasEl"
							class="block h-40 w-full touch-none rounded-[1.25rem] border border-ui-heading bg-white"
							aria-label="Area tanda tangan"
							@pointerdown="mulaiGaris"
							@pointermove="lanjutGaris"
							@pointerup="akhiriGaris"
							@pointercancel="akhiriGaris"
							@pointerleave="akhiriGaris"
						/>
						<p class="mt-1 text-xs text-ui-ink-gray-500">Tanda tangan di area ini.</p>
					</div>
				</div>

				<div class="border-t border-ui-line-gray-200 px-6 py-4">
					<button
						type="submit"
						:disabled="menyimpan"
						class="w-full rounded-[1.25rem] bg-primary py-3.5 text-base font-semibold text-ui-onPrimary transition-colors hover:bg-primary-hover focus:outline-none focus:ring-2 focus:ring-primary focus:ring-offset-2 disabled:opacity-70"
					>
						{{ menyimpan ? 'Menyimpan...' : 'Simpan' }}
					</button>
				</div>
			</form>
		</div>
	</div>
</template>

<script setup>
import { computed, h, nextTick, ref, watch } from 'vue'
import { call } from 'frappe-ui'
import { currentUser } from '../data/user'
import { notifyError, notifySuccess } from '../composables/toast'

const API = 'juragan.api.user_profile_setup.profile'

const Spinner = () =>
	h(
		'svg',
		{
			class: 'animate-spin',
			xmlns: 'http://www.w3.org/2000/svg',
			width: 16,
			height: 16,
			viewBox: '0 0 24 24',
			fill: 'none',
			stroke: 'currentColor',
			'stroke-width': 2,
			'stroke-linecap': 'round',
		},
		[h('path', { d: 'M21 12a9 9 0 1 1-6.219-8.56' })]
	)

const memuat = ref(false)
const gagalMemuat = ref('')
const menyimpan = ref(false)
const profil = ref({})
const noWhatsapp = ref('')

const infoAkun = computed(() => [
	{ label: 'User ID', value: profil.value.user_id, lebar: true },
	{ label: 'Nama Lengkap', value: profil.value.nama_lengkap, lebar: true },
	{ label: 'Cabang', value: profil.value.cabang },
	{ label: 'Kode', value: profil.value.kode },
])

async function muat() {
	memuat.value = true
	gagalMemuat.value = ''
	try {
		const data = (await call(`${API}.get_my_user_juragan`)) || {}
		// Sudah dilengkapi (mis. barusan lewat desk) — tidak perlu layar ini.
		if (data.profile_completed) {
			currentUser.profileRequired = false
			return
		}
		profil.value = data
		noWhatsapp.value = data.no_whatsapp || ''
		memuat.value = false
		await nextTick()
		siapkanCanvas(data.ttd)
	} catch (e) {
		gagalMemuat.value = 'Gagal memuat data profil. Periksa koneksi lalu coba lagi.'
	} finally {
		memuat.value = false
	}
}

watch(
	() => currentUser.profileRequired,
	(wajib) => {
		if (wajib) muat()
	},
	{ immediate: true }
)

// ---------------------------------------------------------------------------
// Signature pad
// ---------------------------------------------------------------------------
// Ukuran piksel canvas ditetapkan sekali saat siap; koordinat pointer lalu
// diskalakan dari ukuran tampilnya. Dengan begitu rotasi layar / resize tidak
// mengosongkan tanda tangan yang sudah digambar.
const canvasEl = ref(null)
const ttdKosong = ref(true)
let ctx = null
let menggambar = false
let titikTerakhir = null

function siapkanCanvas(ttdAwal) {
	const canvas = canvasEl.value
	if (!canvas) return
	const rasio = window.devicePixelRatio || 1
	const rect = canvas.getBoundingClientRect()
	canvas.width = Math.round(rect.width * rasio)
	canvas.height = Math.round(rect.height * rasio)
	ctx = canvas.getContext('2d')
	ctx.lineCap = 'round'
	ctx.lineJoin = 'round'
	ctx.strokeStyle = '#000'
	ctx.lineWidth = 2.5 * rasio
	ttdKosong.value = true

	// Prefill TTD lama (data URL dari field Signature), sama seperti desk.
	if (ttdAwal && String(ttdAwal).startsWith('data:image')) {
		const img = new Image()
		img.onload = () => {
			const skala = Math.min(canvas.width / img.width, canvas.height / img.height, 1)
			const w = img.width * skala
			const tinggi = img.height * skala
			ctx.drawImage(img, (canvas.width - w) / 2, (canvas.height - tinggi) / 2, w, tinggi)
			ttdKosong.value = false
		}
		img.src = ttdAwal
	}
}

function posisi(e) {
	const canvas = canvasEl.value
	const rect = canvas.getBoundingClientRect()
	return {
		x: ((e.clientX - rect.left) / rect.width) * canvas.width,
		y: ((e.clientY - rect.top) / rect.height) * canvas.height,
	}
}

function mulaiGaris(e) {
	if (!ctx) return
	e.preventDefault()
	canvasEl.value.setPointerCapture?.(e.pointerId)
	menggambar = true
	titikTerakhir = posisi(e)
	// Titik tunggal (tap) tetap terlihat.
	ctx.beginPath()
	ctx.arc(titikTerakhir.x, titikTerakhir.y, ctx.lineWidth / 2, 0, Math.PI * 2)
	ctx.fillStyle = '#000'
	ctx.fill()
	ttdKosong.value = false
}

function lanjutGaris(e) {
	if (!menggambar || !ctx) return
	e.preventDefault()
	const titik = posisi(e)
	ctx.beginPath()
	ctx.moveTo(titikTerakhir.x, titikTerakhir.y)
	ctx.lineTo(titik.x, titik.y)
	ctx.stroke()
	titikTerakhir = titik
}

function akhiriGaris() {
	menggambar = false
	titikTerakhir = null
}

function hapusTtd() {
	const canvas = canvasEl.value
	if (!canvas || !ctx) return
	ctx.clearRect(0, 0, canvas.width, canvas.height)
	ttdKosong.value = true
}

/** PNG berlatar putih — format yang sama dengan field Signature desk. */
function dataTtd() {
	const canvas = canvasEl.value
	const salinan = document.createElement('canvas')
	salinan.width = canvas.width
	salinan.height = canvas.height
	const c = salinan.getContext('2d')
	c.fillStyle = '#fff'
	c.fillRect(0, 0, salinan.width, salinan.height)
	c.drawImage(canvas, 0, 0)
	return salinan.toDataURL('image/png')
}

async function simpan() {
	const wa = noWhatsapp.value.trim()
	if (!wa) return notifyError('No WhatsApp wajib diisi.', 'Data belum lengkap')
	if (ttdKosong.value) return notifyError('Tanda tangan (TTD) wajib diisi.', 'Data belum lengkap')

	menyimpan.value = true
	try {
		const hasil = await call(`${API}.complete_my_profile`, {
			no_whatsapp: wa,
			ttd: dataTtd(),
		})
		if (hasil?.ok) {
			currentUser.whatsapp = wa
			currentUser.profileRequired = false
			notifySuccess('Profil tersimpan. Terima kasih!')
		}
	} catch (e) {
		notifyError(e, 'Gagal menyimpan profil')
	} finally {
		menyimpan.value = false
	}
}
</script>
