import { reactive, computed } from 'vue'
import { createResource } from 'frappe-ui'
import { session, sessionUser } from './session'

function getCookie(name) {
	const match = document.cookie.split('; ').find((row) => row.startsWith(name + '='))
	return match ? decodeURIComponent(match.split('=')[1]) : null
}

// Nama awal dari cookie (tersedia instan sebelum fetch server selesai).
function cookieFullName() {
	const fn = getCookie('full_name')
	if (fn && fn !== 'Guest') return fn
	const u = sessionUser()
	return u ? u.split('@')[0] : 'User'
}

/**
 * State user yang sedang login.
 *
 * SUMBER KEBENARAN = session server (endpoint get_my_context):
 *  - user / fullName: dari `frappe.session.user` (bukan cookie yang bisa basi)
 *  - roles: role ASLI Frappe (`frappe.get_roles`) — BUKAN hardcode, BUKAN flag
 *    DocType User Juragan
 *  - rolesLoaded: true setelah fetch selesai (sukses/gagal)
 *
 * Cookie hanya dipakai sebagai nilai awal sementara sebelum fetch selesai.
 */
export const currentUser = reactive({
	user: sessionUser(),
	fullName: cookieFullName(),
	roles: [],
	rolesLoaded: false,
	// Data profil dari DocType User Juragan (diisi oleh get_my_profile).
	idMarketing: '',
	whatsapp: '',
	// No HP dari Master Karyawan — dipakai halaman profil.
	noHp: '',
	joinDate: '',
	// URL asli User.user_image; halaman Profile mengambil isinya via endpoint
	// terautentikasi agar file private juga bekerja di aplikasi native.
	userImage: '',
	// CMO yang belum melengkapi profil (No WhatsApp + TTD) — lihat ProfileSetupScreen.
	profileRequired: false,
	profileLoaded: false,
	email: computed(() => currentUser.user || '—'),
	initials: computed(() => {
		const base = currentUser.fullName || 'U'
		return base
			.split(/[\s.@]+/)
			.filter(Boolean)
			.slice(0, 2)
			.map((w) => w[0]?.toUpperCase())
			.join('')
	}),
})

const contextResource = createResource({
	url: 'juragan.api.portal.roles.get_my_context',
	method: 'GET',
	auto: false,
	onSuccess(data) {
		if (data && typeof data === 'object') {
			if (data.user) currentUser.user = data.user
			if (data.full_name) currentUser.fullName = data.full_name
			currentUser.roles = Array.isArray(data.roles) ? data.roles : []
		} else {
			currentUser.roles = []
		}
		currentUser.rolesLoaded = true
	},
	onError() {
		currentUser.roles = []
		currentUser.rolesLoaded = true
	},
})

const profileResource = createResource({
	url: 'juragan.api.portal.roles.get_my_profile',
	method: 'GET',
	auto: false,
	onSuccess(data) {
		if (data && typeof data === 'object') {
			currentUser.idMarketing = data.id_marketing || ''
			currentUser.whatsapp = data.no_whatsapp || ''
			currentUser.noHp = data.no_hp || ''
			currentUser.joinDate = data.join_date || ''
			currentUser.userImage = data.user_image || ''
			currentUser.profileRequired = !!data.profile_required
			// nama_lengkap dari User Juragan lebih akurat dari cookie kalau ada.
			if (data.nama_lengkap) currentUser.fullName = data.nama_lengkap
		}
		currentUser.profileLoaded = true
	},
	onError() {
		currentUser.profileLoaded = true
	},
})

/** Ambil identitas + role + profil user dari backend. Idempotent. */
export function loadMyRoles() {
	if (!session.isLoggedIn) return
	contextResource.fetch()
	profileResource.fetch()
}

/** Reset saat logout supaya user berikutnya tidak memakai data lama. */
export function resetMyRoles() {
	currentUser.user = sessionUser()
	currentUser.fullName = cookieFullName()
	currentUser.roles = []
	currentUser.rolesLoaded = false
	currentUser.idMarketing = ''
	currentUser.whatsapp = ''
	currentUser.noHp = ''
	currentUser.joinDate = ''
	currentUser.userImage = ''
	currentUser.profileRequired = false
	currentUser.profileLoaded = false
}
