import { readPortalState, writePortalState } from './portalStorage.js'

const SCROLL_SCOPE_PREFIX = 'scroll:'
const RESTORE_DELAY_MS = 140
const RESTORE_RETRY_MS = 100
const RESTORE_MAX_ATTEMPTS = 80
const SCROLL_KEYS = new Set(['ArrowDown', 'ArrowUp', 'End', 'Home', 'PageDown', 'PageUp', ' '])

let activeInstallation = null

export function scrollRouteScope(route) {
	const raw = route?.fullPath || route?.path || route?.name || '/'
	return `${SCROLL_SCOPE_PREFIX}${String(raw).split('#')[0]}`
}

export function normalizeScrollPosition(value) {
	if (!value || typeof value !== 'object') return null
	const top = Number(value.top)
	const left = Number(value.left)
	if (!Number.isFinite(top) || !Number.isFinite(left)) return null
	const normalized = {
		kind: value.kind === 'element' ? 'element' : 'window',
		top: Math.max(0, top),
		left: Math.max(0, left),
	}
	if (value.horizontals && typeof value.horizontals === 'object') {
		const horizontals = {}
		for (const [key, rawLeft] of Object.entries(value.horizontals)) {
			const horizontalLeft = Number(rawLeft)
			if (key && Number.isFinite(horizontalLeft)) {
				horizontals[key] = Math.max(0, horizontalLeft)
			}
		}
		if (Object.keys(horizontals).length) normalized.horizontals = horizontals
	}
	return normalized
}

export function readScrollPosition(user, route, options = {}) {
	if (!user) return null
	return normalizeScrollPosition(
		readPortalState('session', user, scrollRouteScope(route), undefined, options),
	)
}

export function writeScrollPosition(user, route, position, options = {}) {
	const normalized = normalizeScrollPosition(position)
	if (!user || !normalized) return false
	return writePortalState('session', user, scrollRouteScope(route), normalized, options)
}

function isGuestRoute(route) {
	return route?.meta?.guest === true || ['Login', 'ForgotPassword'].includes(route?.name)
}

function isInsideFixedOverlay(element, root) {
	let current = element
	while (current && current !== root) {
		if (window.getComputedStyle(current).position === 'fixed') return true
		current = current.parentElement
	}
	return false
}

function findPrimaryScrollElement() {
	const root = document.getElementById('app')
	if (!root) return null

	const marked = root.querySelector('[data-scroll-restoration="primary"]')
	if (marked) return marked

	const viewportHeight = window.innerHeight || document.documentElement.clientHeight || 0
	const minimumHeight = Math.min(240, viewportHeight * 0.35)
	let best = null
	let bestArea = 0

	for (const element of root.querySelectorAll('.overflow-y-auto, .overflow-auto')) {
		const style = window.getComputedStyle(element)
		if (!/(auto|scroll)/.test(`${style.overflowY} ${style.overflow}`)) continue
		if (style.display === 'none' || style.visibility === 'hidden') continue
		if (isInsideFixedOverlay(element, root)) continue

		const rect = element.getBoundingClientRect()
		if (
			rect.width < 100 ||
			element.clientHeight < minimumHeight ||
			rect.bottom <= 0 ||
			rect.top >= viewportHeight
		) {
			continue
		}

		const visibleHeight = Math.min(rect.bottom, viewportHeight) - Math.max(rect.top, 0)
		const area = Math.max(0, visibleHeight) * rect.width
		if (area > bestArea) {
			best = element
			bestArea = area
		}
	}

	return best
}

function horizontalScrollPositions() {
	const positions = {}
	for (const element of document.querySelectorAll('[data-scroll-restoration-horizontal]')) {
		const key = element.getAttribute('data-scroll-restoration-horizontal')
		if (key) positions[key] = element.scrollLeft
	}
	return positions
}

function applyHorizontalPositions(positions) {
	if (!positions || typeof positions !== 'object') return true
	const pending = new Set(Object.keys(positions))
	let reached = true
	for (const element of document.querySelectorAll('[data-scroll-restoration-horizontal]')) {
		const key = element.getAttribute('data-scroll-restoration-horizontal')
		if (!key || !pending.has(key)) continue
		pending.delete(key)
		element.scrollLeft = positions[key]
		if (Math.abs(element.scrollLeft - positions[key]) > 2) reached = false
	}
	return reached && pending.size === 0
}

function currentScrollTarget() {
	const element = findPrimaryScrollElement()
	const horizontals = horizontalScrollPositions()
	if (element) {
		return {
			kind: 'element',
			top: element.scrollTop,
			left: element.scrollLeft,
			horizontals,
			node: element,
		}
	}
	return {
		kind: 'window',
		top: window.scrollY || window.pageYOffset || 0,
		left: window.scrollX || window.pageXOffset || 0,
		horizontals,
		node: window,
	}
}

function applyPosition(target, position) {
	if (target.kind === 'element') {
		target.node.scrollTop = position.top
		target.node.scrollLeft = position.left
		return {
			top: target.node.scrollTop,
			left: target.node.scrollLeft,
			maxTop: Math.max(0, target.node.scrollHeight - target.node.clientHeight),
		}
	}
	window.scrollTo(position.left, position.top)
	const scrollingElement = document.scrollingElement || document.documentElement
	return {
		top: window.scrollY || window.pageYOffset || scrollingElement.scrollTop || 0,
		left: window.scrollX || window.pageXOffset || scrollingElement.scrollLeft || 0,
		maxTop: Math.max(0, scrollingElement.scrollHeight - scrollingElement.clientHeight),
	}
}

/**
 * Simpan dan pulihkan scroll secara global. Container list yang besar dipilih
 * otomatis; halaman dengan layout khusus dapat menandai target memakai
 * `data-scroll-restoration="primary"`.
 */
export function installScrollRestoration(router, getUser) {
	if (typeof window === 'undefined' || typeof document === 'undefined') return () => {}
	if (activeInstallation?.router === router) return activeInstallation.dispose
	activeInstallation?.dispose()

	try {
		window.history.scrollRestoration = 'manual'
	} catch {
		// Beberapa WebView tidak mengizinkan perubahan properti history ini.
	}

	let restoreGeneration = 0
	let restoreTimer = null

	const cancelRestore = () => {
		restoreGeneration += 1
		if (restoreTimer !== null) window.clearTimeout(restoreTimer)
		restoreTimer = null
	}

	const saveRoute = (route) => {
		const user = getUser?.()
		if (!user || !route?.name || isGuestRoute(route)) return
		const target = currentScrollTarget()
		writeScrollPosition(user, route, target)
	}

	const restoreRoute = (route) => {
		cancelRestore()
		const user = getUser?.()
		if (!user || !route?.name || isGuestRoute(route)) return

		// Route baru dimulai dari atas; route yang pernah dibuka kembali ke posisi
		// terakhirnya. Retry memberi waktu untuk fetch list/infinite-scroll.
		const position = readScrollPosition(user, route) || {
			kind: 'window',
			top: 0,
			left: 0,
		}
		const generation = restoreGeneration
		let attempts = 0
		let stableAttempts = 0

		const attemptRestore = () => {
			if (generation !== restoreGeneration) return
			attempts += 1
			const result = applyPosition(currentScrollTarget(), position)
			const horizontalReached = applyHorizontalPositions(position.horizontals)
			const reached =
				Math.abs(result.top - position.top) <= 2 &&
				Math.abs(result.left - position.left) <= 2 &&
				horizontalReached
			stableAttempts = reached ? stableAttempts + 1 : 0

			if (stableAttempts >= 2 || attempts >= RESTORE_MAX_ATTEMPTS) {
				restoreTimer = null
				return
			}

			// Bila konten belum cukup tinggi, penetapan ke batas bawah juga memicu
			// loader infinite-scroll. Coba lagi setelah data berikutnya dirender.
			restoreTimer = window.setTimeout(attemptRestore, RESTORE_RETRY_MS)
		}

		restoreTimer = window.setTimeout(attemptRestore, RESTORE_DELAY_MS)
	}

	const removeBefore = router.beforeEach((to, from) => {
		saveRoute(from)
		cancelRestore()
		return true
	})
	const removeAfter = router.afterEach((to) => restoreRoute(to))
	const saveCurrentRoute = () => saveRoute(router.currentRoute.value)
	const onVisibilityChange = () => {
		if (document.visibilityState === 'hidden') saveCurrentRoute()
	}
	const onKeyDown = (event) => {
		if (SCROLL_KEYS.has(event.key)) cancelRestore()
	}

	window.addEventListener('pagehide', saveCurrentRoute)
	document.addEventListener('visibilitychange', onVisibilityChange)
	window.addEventListener('wheel', cancelRestore, { passive: true, capture: true })
	window.addEventListener('touchstart', cancelRestore, { passive: true, capture: true })
	window.addEventListener('pointerdown', cancelRestore, { passive: true, capture: true })
	window.addEventListener('keydown', onKeyDown, true)

	const dispose = () => {
		cancelRestore()
		removeBefore?.()
		removeAfter?.()
		window.removeEventListener('pagehide', saveCurrentRoute)
		document.removeEventListener('visibilitychange', onVisibilityChange)
		window.removeEventListener('wheel', cancelRestore, true)
		window.removeEventListener('touchstart', cancelRestore, true)
		window.removeEventListener('pointerdown', cancelRestore, true)
		window.removeEventListener('keydown', onKeyDown, true)
		if (activeInstallation?.router === router) activeInstallation = null
	}

	activeInstallation = { router, dispose }
	return dispose
}
